head.script:
scwin.onpageload = function() {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var opts = {
        "id": "popup_window_1",
        "type": "iframePopup",
        "width": 200 + "px",
        "height": 200 + "px",
        "top": 50,
        "left": 50,
        "popupName": "iframe 팝업1",
        "resizable": true,
        "location": "no",
        "scrollbars": true
            //, "windowDragMove":	"true"
            ,
        "useMaximize": "false"
    };
    $w.openPopup("windowContainer_layer_popup_WESD-24_(WSQ-4143)_sub1.xml", opts);
};
scwin.trigger2_onclick = function(e) {
    var opts = {
        "id": "popup_window_2",
        "type": "iframePopup",
        "width": 200 + "px",
        "height": 200 + "px",
        "top": 50,
        "left": 150,
        "popupName": "iframe 팝업2",
        "resizable": true,
        "location": "no",
        "scrollbars": true
            //, "windowDragMove":	"true"
            ,
        "useMaximize": "false"
    };
    $w.openPopup("windowContainer_layer_popup_WESD-24_(WSQ-4143)_sub1.xml", opts);
};
scwin.trigger3_onclick = function(e) {
    var opts = {
        "id": "popup_window_3",
        "type": "iframePopup",
        "width": 200 + "px",
        "height": 200 + "px",
        "top": 150,
        "left": 50,
