            //, "windowDragMove":	"true"
            ,
        "useMaximize": "false"
    };
    $w.openPopup("windowContainer_layer_popup_WESD-24_(WSQ-4143)_sub1.xml", opts);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
